import Link from "next/link";
import { notFound } from "next/navigation";
import { getPost } from "@/lib/posts";

export default function PostPage({ params }: { params: { slug: string } }) {
  const post = getPost("lab", params.slug);
  const active = "lab" as const;

  if (!post) notFound();

  return (
    <main className="fixed inset-0 bg-black overflow-hidden">
      <div
        className="absolute inset-0 bg-center bg-no-repeat bg-contain"
        style={{ backgroundImage: "url(/images/contents_bg.jpg)" }}
      />

      <div className="relative z-10 h-full max-w-4xl mx-auto px-6 py-10 text-white">
        <div className="flex items-start justify-between">
          <div>
            <div className="text-xs tracking-[0.22em] text-white/70">CATEGORY</div>
            <h1 className="text-2xl mt-1">AI CONTENTS</h1>

            <nav className="mt-4 flex gap-6 text-sm tracking-[0.18em] uppercase">
              <Link
                href="/ai"
                className={
                  active === "work"
                    ? "cursor-pointer transition text-white"
                    : "cursor-pointer transition text-white/50 hover:text-white/80"
                }
              >
                Work
              </Link>
              <Link
                href="/ai/lab"
                className={
                  active === "lab"
                    ? "cursor-pointer transition text-white"
                    : "cursor-pointer transition text-white/50 hover:text-white/80"
                }
              >
                Lab
              </Link>
              <Link
                href="/ai/article"
                className={
                  active === "article"
                    ? "cursor-pointer transition text-white"
                    : "cursor-pointer transition text-white/50 hover:text-white/80"
                }
              >
                Article
              </Link>
            </nav>

          </div>

          <Link
            href="/?select=1"
            className="cursor-pointer px-4 py-2 rounded-full border border-white/20 bg-black/30 backdrop-blur-md hover:bg-white hover:text-black transition"
          >
            BACK
          </Link>
        </div>

        <div className="mt-8 h-[calc(100%-5.5rem)] overflow-auto pr-1">
          <div className="rounded-2xl border border-white/15 bg-black/25 backdrop-blur-md p-6">
            <div className="text-sm tracking-wide text-white/70">{post.date}</div>
            <h2 className="mt-2 text-2xl">{post.title}</h2>

            {post.source ? (
              <a
                href={post.source}
                target="_blank"
                rel="noreferrer"
                className="inline-block mt-3 text-sm text-white/70 underline hover:text-white"
              >
                Source
              </a>
            ) : null}

            {post.tags && post.tags.length ? (
              <div className="mt-4 flex flex-wrap gap-2">
                {post.tags.map((t) => (
                  <span
                    key={t}
                    className="text-xs px-2 py-1 rounded-full border border-white/15 text-white/70"
                  >
                    {t}
                  </span>
                ))}
              </div>
            ) : null}

            <div className="mt-6 whitespace-pre-wrap text-white/90 text-sm leading-relaxed">
              {post.body}
            </div>

            <div className="mt-8">
              <Link
                href="/ai/lab"
                className="cursor-pointer text-sm text-white/70 hover:text-white underline"
              >
                목록으로
              </Link>
            </div>
          </div>
        </div>
      </div>
    </main>
  );
}
